(990005, 117468, 26756, '<td valign="top">Beautiful pic.  You made a very complimentary frame around it too.  The white feathers look natural without being blown out.</td>', 'Beautiful pic.  You made a very complimentary frame around it too.  The white feathers look natural without being blown out.', '2004-11-03 20:46:51.000000', NULL, 1),
(990018, 118035, 10985, '<td valign="top">Despite the awesome light on the side of the mountain, I see two major flaws in this otherwise excellent shot: the horizon is very tilted and there is a large blown out white patch in the sky. For your own pleasure, you could fix those easily enough to make this a very strong image.</td>', 'Despite the awesome light on the side of the mountain, I see two major flaws in this otherwise excellent shot: the horizon is very tilted and there is a large blown out white patch in the sky. For your own pleasure, you could fix those easily enough to make this a very strong image.', '2004-11-03 20:53:22.000000', NULL, 1),
