(992059, 117900, 27556, '<td valign="top">i find the background a bit distracting</td>', 'i find the background a bit distracting', '2004-11-04 16:37:34.000000', NULL, 1),
(992061, 117978, 19831, '<td valign="top">Good capture that fits the spirit of the challenge. Lighting is not bad for being outdoors. Compositionally, I feel this shot might be improved with perhaps a tighter cropping, maybe frame the duck not in the center (ROT), he kind of gets lost in all the brown. Also, the fence sort of makes a "horizon", and you could try leveling it, although I don''t think it is a real big deal in this particular case. I think your border in this case is kind of nice. Tastefully subtle and ties in nicely the bits of grass in the photo.</td>', 'Good capture that fits the spirit of the challenge. Lighting is not bad for being outdoors. Compositionally, I feel this shot might be improved with perhaps a tighter cropping, maybe frame the duck not in the center (ROT), he kind of gets lost in all the brown. Also, the fence sort of makes a "horizon", and you could try leveling it, although I don''t think it is a real big deal in this particular case. I think your border in this case is kind of nice. Tastefully subtle and ties in nicely the bits of grass in the photo.', '2004-11-04 16:38:39.000000', NULL, 1),
(992062, 117353, 27556, '<td valign="top">i love this so creepy, and mysterious</td>', 'i love this so creepy, and mysterious', '2004-11-04 16:39:28.000000', NULL, 1);
