(994015, 116270, 22970, '<td valign="top">Very nice micro with great detail, DOF, Focus, and lighting but I see nothing bizarre or anything that makes me wonder in amazement. You have a great picture but imo I does not meet the challenge.</td>', 'Very nice micro with great detail, DOF, Focus, and lighting but I see nothing bizarre or anything that makes me wonder in amazement. You have a great picture but imo I does not meet the challenge.', '2004-11-05 19:23:05.000000', NULL, 1),
(994022, 115926, 22970, '<td valign="top">Good capture but I think a tighter crop would of made this picture even better. I consider it amazing how a bird can see fish under water and dive to get lunch. IMO you meet the challenge and have a good photo.</td>', 'Good capture but I think a tighter crop would of made this picture even better. I consider it amazing how a bird can see fish under water and dive to get lunch. IMO you meet the challenge and have a good photo.', '2004-11-05 19:25:48.000000', NULL, 1),
(994030, 117679, 4226, '<td valign="top">out of focus</td>', 'out of focus', '2004-11-05 19:29:20.000000', NULL, 1),
(994032, 118052, 22970, '<td valign="top">Im sorry but I dont see anything bizarre about your photo or amazing. Looks like a dirt hill on the backside of a soccer field. However you did a good job of capturing a mars type landscape or as your title say then end of earth. The goal and out of bound flag [?] to the left is distracting. Lighting is good and photo is smooth</td>', 'Im sorry but I dont see anything bizarre about your photo or amazing. Looks like a dirt hill on the backside of a soccer field. However you did a good job of capturing a mars type landscape or as your title say then end of earth. The goal and out of bound flag [?] to the left is distracting. Lighting is good and photo is smooth', '2004-11-05 19:30:17.000000', NULL, 1),
(994037, 118142, 27761, '<td valign="top">the vote is in great pic</td>', 'the vote is in great pic', '2004-11-05 19:33:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(994040, 118085, 22970, '<td valign="top">Finally a picture that meets the challenge in my opinion with good detail, color, and focus; However the sky is a little burned out and the boarder imo is overpowering, but still a good photo.</td>', 'Finally a picture that meets the challenge in my opinion with good detail, color, and focus; However the sky is a little burned out and the boarder imo is overpowering, but still a good photo.', '2004-11-05 19:34:57.000000', NULL, 1),
(994044, 118051, 22970, '<td valign="top">I think you took a good micro image but imo I dont see anything bizarre or amazing. I dont feel as if it meets the challenge. As for your photo, lighting is good along with the focus on your subject. The background is a bit distracting. If this picture were placed in a micro challenge I believe it would of done better.</td>', 'I think you took a good micro image but imo I dont see anything bizarre or amazing. I dont feel as if it meets the challenge. As for your photo, lighting is good along with the focus on your subject. The background is a bit distracting. If this picture were placed in a micro challenge I believe it would of done better.', '2004-11-05 19:41:37.000000', NULL, 1),
(994045, 116658, 17809, '<td valign="top">the sun is a bit overexposed,but otherwise the photo is excellent.I don''t understand what is bizarre in this picture? 6</td>', 'the sun is a bit overexposed,but otherwise the photo is excellent.I don''t understand what is bizarre in this picture? 6', '2004-11-05 19:43:22.000000', NULL, 1),
(994048, 117906, 22970, '<td valign="top">I think you photo meets the challenge in an interpretation way. I think you took a good photo with good lighting and composition. I like the black background and the border works well.</td>', 'I think you photo meets the challenge in an interpretation way. I think you took a good photo with good lighting and composition. I like the black background and the border works well.', '2004-11-05 19:47:54.000000', NULL, 1),
(994053, 117388, 22970, '<td valign="top">That is wild how it is growing up the three. Nice colors but think a different angle would of worked better. There are some lines on the left that is somewhat distracting. Good photo!</td>', 'That is wild how it is growing up the three. Nice colors but think a different angle would of worked better. There are some lines on the left that is somewhat distracting. Good photo!', '2004-11-05 19:52:35.000000', NULL, 1),
(994056, 115898, 24363, '<td valign="top">and this is bizarre because?</td>', 'and this is bizarre because?', '2004-11-05 19:56:18.000000', NULL, 1),
(994061, 116563, 22970, '<td valign="top">Im sorry but what is so bizarre or amazing about a snow-covered ground and not on the tree? That happens a lot as you can see from the tree in the background. As far as the photograph goes it good but I would of cropped in tighter and leveled the tree vertically.</td>', 'Im sorry but what is so bizarre or amazing about a snow-covered ground and not on the tree? That happens a lot as you can see from the tree in the background. As far as the photograph goes it good but I would of cropped in tighter and leveled the tree vertically.', '2004-11-05 19:58:22.000000', NULL, 1),
(994064, 117186, 22970, '<td valign="top">Screams AFLAC, AFLAC to me. That was my first impression when I saw it as I smiled. So you meet the challenge with a good sound photo. Lighting, DOF, and focus good. Great job!</td>', 'Screams AFLAC, AFLAC to me. That was my first impression when I saw it as I smiled. So you meet the challenge with a good sound photo. Lighting, DOF, and focus good. Great job!', '2004-11-05 20:01:27.000000', NULL, 1),
(994066, 116963, 24363, '<td valign="top">great shot</td>', 'great shot', '2004-11-05 20:01:46.000000', NULL, 1),
(994069, 117194, 22970, '<td valign="top">Im sorry but I dont see anything bizarre or amazing about this photo. The focus seems to be off as well.</td>', 'Im sorry but I dont see anything bizarre or amazing about this photo. The focus seems to be off as well.', '2004-11-05 20:03:23.000000', NULL, 1),
(994077, 117029, 22970, '<td valign="top">Be honest [a I am not trying to be rude] what is bizarre or amazing about this photo. It does not meet the challenge even though it is a good photograph. Beautiful sky and detail.</td>', 'Be honest [a I am not trying to be rude] what is bizarre or amazing about this photo. It does not meet the challenge even though it is a good photograph. Beautiful sky and detail.', '2004-11-05 20:07:03.000000', NULL, 1),
(994081, 118100, 22970, '<td valign="top">Great photo with good color, lighting, and focus. And it meets the challenge!<br/> <br/></td>', 'Great photo with good color, lighting, and focus. And it meets the challenge! ', '2004-11-05 20:09:08.000000', NULL, 1),
(994091, 117094, 24363, '<td valign="top">i love the picture adorible</td>', 'i love the picture adorible', '2004-11-05 20:15:34.000000', NULL, 1),
(994094, 116371, 22970, '<td valign="top">I believe there is something in this photo that make is bizarre but I cant see it right now. So Im going to comment now and come back later to see if I can find what makes it meet the challenge. Then I will vote on it. I believe in giving photo a chance. <br/> <br/>Ok Im back to you picture and still cant see it. But the photo is good. Focus a little off, good lighting.<br/> <br/> <br/> <br/> <br/> <br/></td>', 'I believe there is something in this photo that make is bizarre but I cant see it right now. So Im going to comment now and come back later to see if I can find what makes it meet the challenge. Then I will vote on it. I believe in giving photo a chance.  Ok Im back to you picture and still cant see it. But the photo is good. Focus a little off, good lighting.     ', '2004-11-05 20:18:25.000000', NULL, 1),
(994253, 117880, 23913, '<td valign="top">i really like this shot it seems almost like its a painting only its not...<br/> <br/>oh well its an awsome shot! GL</td>', 'i really like this shot it seems almost like its a painting only its not... oh well its an awsome shot! GL', '2004-11-05 22:11:03.000000', NULL, 1),
(994255, 115986, 23913, '<td valign="top">could have been a cool shot for wacky foods too.<br/> <br/>nice</td>', 'could have been a cool shot for wacky foods too. nice', '2004-11-05 22:12:41.000000', NULL, 1),
