(994964, 118150, 27440, '<td valign="top">I would say something but I lost my jaw :P</td>', 'I would say something but I lost my jaw :P', '2004-11-06 08:43:42.000000', NULL, 1),
(994968, 116512, 27440, '<td valign="top">The frame is superb.<br/>The colours are very beautifull although they hurt your eyes a bit.</td>', 'The frame is superb.The colours are very beautifull although they hurt your eyes a bit.', '2004-11-06 08:45:08.000000', NULL, 1),
(994969, 116779, 27440, '<td valign="top">HAHAHHAHAAH Adorable. Meets the chalange :)</td>', 'HAHAHHAHAAH Adorable. Meets the chalange :)', '2004-11-06 08:47:10.000000', NULL, 1),
(994973, 117024, 3724, '<td valign="top">great title......</td>', 'great title......', '2004-11-06 08:52:09.000000', NULL, 1),
(995015, 117931, 23141, '<td valign="top">Excellent macro shot and good capture of a truly bizarre bug!  You even got those weird little eyeballs :)</td>', 'Excellent macro shot and good capture of a truly bizarre bug!  You even got those weird little eyeballs :)', '2004-11-06 09:40:52.000000', NULL, 1),
(995020, 116084, 23141, '<td valign="top">As someone who''s spent hours trying to get a good lightning shot, I have to say: congrats on capturing the defining moment!</td>', 'As someone who''s spent hours trying to get a good lightning shot, I have to say: congrats on capturing the defining moment!', '2004-11-06 09:42:56.000000', NULL, 1),
(995041, 117493, 22365, '<td valign="top">Nice colors!</td>', 'Nice colors!', '2004-11-06 10:08:24.000000', NULL, 1),
(995058, 116578, 23141, '<td valign="top">I like this picture a lot and think it''s very creative in terms of color, subject, lighting...  But I don''t think it''s completely natural, so I''m bumping it down a little.</td>', 'I like this picture a lot and think it''s very creative in terms of color, subject, lighting...  But I don''t think it''s completely natural, so I''m bumping it down a little.', '2004-11-06 10:35:41.000000', NULL, 1),
(995060, 116327, 23141, '<td valign="top">Absolutely disgustingly bizarre.  Nice use of light, and I for one like the frame.</td>', 'Absolutely disgustingly bizarre.  Nice use of light, and I for one like the frame.', '2004-11-06 10:37:06.000000', NULL, 1),
(995061, 117464, 23141, '<td valign="top">Truly bizarre bug and a great macro.  Good use of lighting to bring out the details.  I feel the composition would have been better with the eye of the shell in a more prominent position inside the picture.</td>', 'Truly bizarre bug and a great macro.  Good use of lighting to bring out the details.  I feel the composition would have been better with the eye of the shell in a more prominent position inside the picture.', '2004-11-06 10:39:14.000000', NULL, 1),
(995065, 117756, 23141, '<td valign="top">I like that you''ve found something completely natural and strange in keeping with the challenge.  The angle you chose really brings out the facial features.  It would be even better if the leaf were removed from in front of the "eye" and the picture didn''t look so...  (sharpened?).</td>', 'I like that you''ve found something completely natural and strange in keeping with the challenge.  The angle you chose really brings out the facial features.  It would be even better if the leaf were removed from in front of the "eye" and the picture didn''t look so...  (sharpened?).', '2004-11-06 10:45:29.000000', NULL, 1),
(995070, 118085, 23141, '<td valign="top">Completely natural and unusual.  Nice depth of field.  Wonder what the picture would be like in a more square format where the "points" of the star didn''t hit the edges of the picture?</td>', 'Completely natural and unusual.  Nice depth of field.  Wonder what the picture would be like in a more square format where the "points" of the star didn''t hit the edges of the picture?', '2004-11-06 10:48:26.000000', NULL, 1),
(995071, 117281, 23141, '<td valign="top">Beautiful, lovely, and amazing.  Nice colors and light in this picture.</td>', 'Beautiful, lovely, and amazing.  Nice colors and light in this picture.', '2004-11-06 10:49:27.000000', NULL, 1),
(995074, 116351, 23141, '<td valign="top">Definitely a bizarre little fruit.  Nice soft lighting.  An unblemished fruit would have made for a better subject, though.</td>', 'Definitely a bizarre little fruit.  Nice soft lighting.  An unblemished fruit would have made for a better subject, though.', '2004-11-06 10:52:06.000000', NULL, 1),
(995078, 117159, 23141, '<td valign="top">Odd little bird - I like the way he seems to eye you as if daring you to make fun of him.  Nice composition and detail, but seems to be a little misty... shot through a window or a screen?</td>', 'Odd little bird - I like the way he seems to eye you as if daring you to make fun of him.  Nice composition and detail, but seems to be a little misty... shot through a window or a screen?', '2004-11-06 10:54:21.000000', NULL, 1),
(995079, 117968, 23141, '<td valign="top">Lovely portrait of a beautiful cat, but doesn''t seem to be in keeping with the bizarre/humorous challenge</td>', 'Lovely portrait of a beautiful cat, but doesn''t seem to be in keeping with the bizarre/humorous challenge', '2004-11-06 10:55:41.000000', NULL, 1),
(995080, 116779, 23141, '<td valign="top">Good capture of a humorous expression on a goose :)</td>', 'Good capture of a humorous expression on a goose :)', '2004-11-06 10:56:49.000000', NULL, 1),
(995081, 116932, 23141, '<td valign="top">Too funny!  Cute subject with great colors, but focusing looks to be off a bit.</td>', 'Too funny!  Cute subject with great colors, but focusing looks to be off a bit.', '2004-11-06 10:58:07.000000', NULL, 1),
(995082, 118069, 23141, '<td valign="top">Certainly one of nature''s most bizarre critters.  Nice lighting and depth of field!</td>', 'Certainly one of nature''s most bizarre critters.  Nice lighting and depth of field!', '2004-11-06 10:59:29.000000', NULL, 1),
(995083, 118114, 23141, '<td valign="top">Strange, twisty, and spiny!</td>', 'Strange, twisty, and spiny!', '2004-11-06 11:00:54.000000', NULL, 1),
(995087, 117437, 23141, '<td valign="top">Love it!  Cute and silly.  Could have been a bit brighter, but you can''t plan a shot like this unless you''re the zookeeper! :)</td>', 'Love it!  Cute and silly.  Could have been a bit brighter, but you can''t plan a shot like this unless you''re the zookeeper! :)', '2004-11-06 11:08:51.000000', NULL, 1),
(995088, 118110, 23141, '<td valign="top">Great macro and lovely soft colors.  Would showing more space underneath the snail have given a greater sense of his strange balancing abilities?</td>', 'Great macro and lovely soft colors.  Would showing more space underneath the snail have given a greater sense of his strange balancing abilities?', '2004-11-06 11:13:00.000000', NULL, 1),
(995089, 116852, 23141, '<td valign="top">I do laugh every time I see ducks with their tails in the air on the pond in our park.  Nice colors, angle, and composition in this one!</td>', 'I do laugh every time I see ducks with their tails in the air on the pond in our park.  Nice colors, angle, and composition in this one!', '2004-11-06 11:13:49.000000', NULL, 1),
(995092, 115945, 23141, '<td valign="top">Nice idea, but the picture needs a little work.  More light and better focusing would have helped to capture the details.</td>', 'Nice idea, but the picture needs a little work.  More light and better focusing would have helped to capture the details.', '2004-11-06 11:17:34.000000', NULL, 1),
(995132, 117837, 26643, '<td valign="top">The dark tree creates an interesting contrast to the clouds &amp; sky.</td>', 'The dark tree creates an interesting contrast to the clouds & sky.', '2004-11-06 12:10:32.000000', NULL, 1),
(995252, 116342, 27524, '<td valign="top">Good B&amp;W... lovely contrast of colors.</td>', 'Good B&W... lovely contrast of colors.', '2004-11-06 13:08:33.000000', NULL, 1),
