(995496, 117094, 5746, '<td valign="top">Very cute picture. You captured rare moment. The dog''s expression is almost human. Maybe not bizzare but heart touching. 9.</td>', 'Very cute picture. You captured rare moment. The dog''s expression is almost human. Maybe not bizzare but heart touching. 9.', '2004-11-06 16:04:48.000000', NULL, 1),
(995498, 118018, 5746, '<td valign="top">Great idea! I wish it was more saturated, but you have enormous imagination :) Congrats! 9.</td>', 'Great idea! I wish it was more saturated, but you have enormous imagination :) Congrats! 9.', '2004-11-06 16:06:07.000000', NULL, 1),
(995500, 117218, 5746, '<td valign="top">Punk Catapilar :) 7.</td>', 'Punk Catapilar :) 7.', '2004-11-06 16:07:04.000000', NULL, 1),
(995502, 115898, 5746, '<td valign="top">I guess you wanted to show her hair, which is really amazing. I wish you used different angle and that the picture was bigger. She ia absolutely gorgious girl. 8.</td>', 'I guess you wanted to show her hair, which is really amazing. I wish you used different angle and that the picture was bigger. She ia absolutely gorgious girl. 8.', '2004-11-06 16:08:13.000000', NULL, 1),
(995504, 118150, 5746, '<td valign="top">I really believe sunsets can be amazing. 10. No doubts about it.</td>', 'I really believe sunsets can be amazing. 10. No doubts about it.', '2004-11-06 16:09:18.000000', NULL, 1),
(995506, 117875, 5746, '<td valign="top">You captured a lot of detail here. I don''t know, I think I would like it to have more space around it to focus on the whole seed. 8.</td>', 'You captured a lot of detail here. I don''t know, I think I would like it to have more space around it to focus on the whole seed. 8.', '2004-11-06 16:10:42.000000', NULL, 1),
(995507, 115992, 5746, '<td valign="top">:) What a moment. I think you cropped the poor bird too much, but I like it. It''s funny and it tells a story. 7.</td>', ':) What a moment. I think you cropped the poor bird too much, but I like it. It''s funny and it tells a story. 7.', '2004-11-06 16:11:42.000000', NULL, 1),
(995510, 116701, 5746, '<td valign="top">Wooow.  I wished I could see more of the tree. 8.</td>', 'Wooow.  I wished I could see more of the tree. 8.', '2004-11-06 16:12:33.000000', NULL, 1),
(995512, 117281, 5746, '<td valign="top">Space Oddity. Very nice atmosphere. Looks like an UFO to me. I don''t know what are the red dots on the picture. I wish it was sharpened a bit. 9.</td>', 'Space Oddity. Very nice atmosphere. Looks like an UFO to me. I don''t know what are the red dots on the picture. I wish it was sharpened a bit. 9.', '2004-11-06 16:14:41.000000', NULL, 1),
