(995516, 118140, 5746, '<td valign="top">If you took it from a different angle (more to the right) and cropped it so the fungus is in the center, it would''ve help I think. But IT IS amazing. 8.</td>', 'If you took it from a different angle (more to the right) and cropped it so the fungus is in the center, it would''ve help I think. But IT IS amazing. 8.', '2004-11-06 16:17:51.000000', NULL, 1),
(995517, 117501, 19333, '<td valign="top">I like the idea, to me the leaf is too small (ok, you cannot control that:) and the focus isn''t clearly on it as the title suggests. Maybe a tighter crop  or bigger zoom will do (besides a larger leaf ;-)</td>', 'I like the idea, to me the leaf is too small (ok, you cannot control that:) and the focus isn''t clearly on it as the title suggests. Maybe a tighter crop  or bigger zoom will do (besides a larger leaf ;-)', '2004-11-06 16:17:54.000000', NULL, 1),
(995518, 117906, 22046, '<td valign="top">Definitely bizarre. Excellent use of the black background and directional ligh.</td>', 'Definitely bizarre. Excellent use of the black background and directional ligh.', '2004-11-06 16:18:25.000000', NULL, 1),
(995520, 117889, 5746, '<td valign="top">Great title :) You''ve got an eye for the little things. 8.</td>', 'Great title :) You''ve got an eye for the little things. 8.', '2004-11-06 16:19:44.000000', NULL, 1),
(995522, 117468, 22046, '<td valign="top">Yeeps! Is that a fish in his mouth? Great catch.</td>', 'Yeeps! Is that a fish in his mouth? Great catch.', '2004-11-06 16:19:51.000000', NULL, 1),
(995523, 117845, 22046, '<td valign="top">Never saw one of these before. Excellent choise for this topic. I''m wondering if this could be just a tad brighter with a bit more contrast? But still marvelous.</td>', 'Never saw one of these before. Excellent choise for this topic. I''m wondering if this could be just a tad brighter with a bit more contrast? But still marvelous.', '2004-11-06 16:20:44.000000', NULL, 1),
(995524, 118018, 22046, '<td valign="top">Funny and cleverly done. Glad for the deep depth of field. It wouldn''t have worked as well without it.</td>', 'Funny and cleverly done. Glad for the deep depth of field. It wouldn''t have worked as well without it.', '2004-11-06 16:21:31.000000', NULL, 1),
