(1000929, 118069, 24511, '<td valign="top">You get points for weird just for chosing this subject.  I found the lighting unattractive but the contrasting lighter shade in the background very helpfull to depict form.  Good one.  7</td>', 'You get points for weird just for chosing this subject.  I found the lighting unattractive but the contrasting lighter shade in the background very helpfull to depict form.  Good one.  7', '2004-11-09 12:27:49.000000', NULL, 1),
