(1000942, 118141, 24511, '<td valign="top">Image seemed fabricated.  Weird points for subject and triangle composition.  White background very ordinary.  Thanks for showing the full view.  Very interesting creature.  6</td>', 'Image seemed fabricated.  Weird points for subject and triangle composition.  White background very ordinary.  Thanks for showing the full view.  Very interesting creature.  6', '2004-11-09 12:37:20.000000', NULL, 1),
(1000945, 116917, 24511, '<td valign="top">You should get 0 if this is a plastic plant.  For now get my second 10 vote with great lighting, wowness and weirdness.  Thanks.</td>', 'You should get 0 if this is a plastic plant.  For now get my second 10 vote with great lighting, wowness and weirdness.  Thanks.', '2004-11-09 12:39:16.000000', NULL, 1),
(1000949, 118126, 24511, '<td valign="top">I thought ostriges were the only birds to stick their heads in the sand.  Don''t they make a beautiful couple?  Great 8.  Thanks.</td>', 'I thought ostriges were the only birds to stick their heads in the sand.  Don''t they make a beautiful couple?  Great 8.  Thanks.', '2004-11-09 12:40:41.000000', NULL, 1),
(1000960, 118021, 24511, '<td valign="top">Eye don''t get it?  Just kidding.  Splendid photo.  Is it a creation or simply a natural phenomena?  Niner all the way.<br/>By the way, you''ve got some scum to clean out of your left inner eye.</td>', 'Eye don''t get it?  Just kidding.  Splendid photo.  Is it a creation or simply a natural phenomena?  Niner all the way.By the way, you''ve got some scum to clean out of your left inner eye.', '2004-11-09 12:43:46.000000', NULL, 1),
(1000965, 117121, 24511, '<td valign="top">Sure looks like man made material to me.  If there is indeed such a thing as a Yucca plant then you have my weird votes.  9</td>', 'Sure looks like man made material to me.  If there is indeed such a thing as a Yucca plant then you have my weird votes.  9', '2004-11-09 12:46:04.000000', NULL, 1),
(1000976, 118033, 24511, '<td valign="top">Funny dramatic story telling photo.  Weird indeed.  Would have scored higher if there was a direct link to the nature theme.  Thanks for sharing.</td>', 'Funny dramatic story telling photo.  Weird indeed.  Would have scored higher if there was a direct link to the nature theme.  Thanks for sharing.', '2004-11-09 12:50:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1000984, 118100, 24511, '<td valign="top">I was not expecting to vote three 10''s this challenge but here it is.  I am not even going to try to critique this weird paranormal phenomena.  Is there a scientific explanation for this?  Nice shot.</td>', 'I was not expecting to vote three 10''s this challenge but here it is.  I am not even going to try to critique this weird paranormal phenomena.  Is there a scientific explanation for this?  Nice shot.', '2004-11-09 12:53:49.000000', NULL, 1),
