(1001965, 115990, 29009, '<td valign="top">I laughed out loud when I saw this.  Great job!  I''m not sure if red-eye correction was allowed, but if it was that is the only thing I see that could be improved.</td>', 'I laughed out loud when I saw this.  Great job!  I''m not sure if red-eye correction was allowed, but if it was that is the only thing I see that could be improved.', '2004-11-09 21:31:09.000000', NULL, 1),
(1001966, 117880, 29009, '<td valign="top">Wow!  This rock seems to balance right on the edge.  Congratulations - I hope it wins something.</td>', 'Wow!  This rock seems to balance right on the edge.  Congratulations - I hope it wins something.', '2004-11-09 21:31:50.000000', NULL, 1),
(1001967, 117078, 29009, '<td valign="top">This sucker sure is ugly but I like your composition and use of a shallow depth of field.</td>', 'This sucker sure is ugly but I like your composition and use of a shallow depth of field.', '2004-11-09 21:32:34.000000', NULL, 1),
(1001970, 116868, 29009, '<td valign="top">This picture definitely got a reaction from me!  It looks like the tree is shedding dry skin....wonderful shot.</td>', 'This picture definitely got a reaction from me!  It looks like the tree is shedding dry skin....wonderful shot.', '2004-11-09 21:33:28.000000', NULL, 1),
(1001973, 117468, 29009, '<td valign="top">Wow!  Great shot!  I love the framing.  One small thing - it looks like you''ve lost the curve of the head but I didn''t notice that right away.  How lucky for you to have been in the right place at the right time!  Congratulations.</td>', 'Wow!  Great shot!  I love the framing.  One small thing - it looks like you''ve lost the curve of the head but I didn''t notice that right away.  How lucky for you to have been in the right place at the right time!  Congratulations.', '2004-11-09 21:35:28.000000', NULL, 1),
(1001975, 116057, 29009, '<td valign="top">This photo is very dramatic.  The power lines are distracting, but you must have really enjoyed the show.</td>', 'This photo is very dramatic.  The power lines are distracting, but you must have really enjoyed the show.', '2004-11-09 21:36:27.000000', NULL, 1),
(1001977, 115898, 29009, '<td valign="top">Very pretty model.  I don''t believe it belongs in the challenge, perhaps you put it here by mistake?</td>', 'Very pretty model.  I don''t believe it belongs in the challenge, perhaps you put it here by mistake?', '2004-11-09 21:37:38.000000', NULL, 1),
(1001978, 117381, 29009, '<td valign="top">This is a very nice picture, but it''s not bizarre.</td>', 'This is a very nice picture, but it''s not bizarre.', '2004-11-09 21:38:26.000000', NULL, 1),
(1001981, 118040, 29009, '<td valign="top">This photo is too small.</td>', 'This photo is too small.', '2004-11-09 21:39:40.000000', NULL, 1),
(1001984, 116327, 29009, '<td valign="top">Is this larvae mounted on something?  The lines are distracting.  What I do like is the way you had the focal point lead into the picture over the border.</td>', 'Is this larvae mounted on something?  The lines are distracting.  What I do like is the way you had the focal point lead into the picture over the border.', '2004-11-09 21:41:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1001986, 118202, 29009, '<td valign="top">This is a good shot.  The tree in the foreground distracts from the overall mood.  I really like the inclusion of a person for scale.</td>', 'This is a good shot.  The tree in the foreground distracts from the overall mood.  I really like the inclusion of a person for scale.', '2004-11-09 21:42:48.000000', NULL, 1),
