(1002038, 116294, 26799, '<td valign="top">I like how the corn stands out in this picture. Did you do any desaturation post shot? Great shot.</td>', 'I like how the corn stands out in this picture. Did you do any desaturation post shot? Great shot.', '2004-11-09 22:12:35.000000', NULL, 1),
(1002040, 115907, 26799, '<td valign="top">Interesting shot. Did you stumble on this or plan it?</td>', 'Interesting shot. Did you stumble on this or plan it?', '2004-11-09 22:13:12.000000', NULL, 1),
(1002042, 118107, 29009, '<td valign="top">This is a great shot.  I love the focus, the detail in the extended claws is fantastic.  I''m rating it slightly lower than I might otherwise as I don''t see the connection to "bizarre" nature.  Kittlens playing with string is fairly common, and the photo was taken indoors.  I do like the shot very much.</td>', 'This is a great shot.  I love the focus, the detail in the extended claws is fantastic.  I''m rating it slightly lower than I might otherwise as I don''t see the connection to "bizarre" nature.  Kittlens playing with string is fairly common, and the photo was taken indoors.  I do like the shot very much.', '2004-11-09 22:14:36.000000', NULL, 1),
(1002043, 115898, 26799, '<td valign="top">I am missing the connection between bizaare nature and your shot. It could be perhaps her beautiful long hair, but don''t know if it''s really bizaare. Nice picture though!</td>', 'I am missing the connection between bizaare nature and your shot. It could be perhaps her beautiful long hair, but don''t know if it''s really bizaare. Nice picture though!', '2004-11-09 22:14:44.000000', NULL, 1),
