(1002177, 116658, 22479, '<td valign="top">Nice scene with subtle shades and good exposure. Not bizarre, but still an excellent composition.</td>', 'Nice scene with subtle shades and good exposure. Not bizarre, but still an excellent composition.', '2004-11-09 23:15:08.000000', NULL, 1),
(1002180, 117967, 22479, '<td valign="top">Excellent! I like the idea here, but this is a tad bit overexposed. However it still works, and my favorite of the bunch. Nice job! 10</td>', 'Excellent! I like the idea here, but this is a tad bit overexposed. However it still works, and my favorite of the bunch. Nice job! 10', '2004-11-09 23:16:10.000000', NULL, 1),
(1002182, 117190, 15811, '<td valign="top">I like this shot -- very interesting to see it captured so greatly.  The only thing I can think that could improve it would be if the lighting lit the subject up a little more...like if you were on the other side.  Otherwise, great composition, focus is good, and interesting subject. good job!</td>', 'I like this shot -- very interesting to see it captured so greatly.  The only thing I can think that could improve it would be if the lighting lit the subject up a little more...like if you were on the other side.  Otherwise, great composition, focus is good, and interesting subject. good job!', '2004-11-09 23:16:14.000000', NULL, 1),
(1002183, 116084, 22479, '<td valign="top">Amazing shot, always special to catch a bolt of lightning, particularly exposed as well as this one. One of the best of the bunch.</td>', 'Amazing shot, always special to catch a bolt of lightning, particularly exposed as well as this one. One of the best of the bunch.', '2004-11-09 23:17:29.000000', NULL, 1),
(1002184, 116758, 15811, '<td valign="top">I like the image -- good composition and the focus and colors look really good.</td>', 'I like the image -- good composition and the focus and colors look really good.', '2004-11-09 23:17:38.000000', NULL, 1),
(1002186, 116086, 15811, '<td valign="top">I really like the shot a lot.  Interesting choice of location, I''ve never seen anything like that myself.  It could be stronger, however, if that whole hillside had more light on it.  Otherwise, very nice shot.</td>', 'I really like the shot a lot.  Interesting choice of location, I''ve never seen anything like that myself.  It could be stronger, however, if that whole hillside had more light on it.  Otherwise, very nice shot.', '2004-11-09 23:19:01.000000', NULL, 1),
(1002188, 116512, 22479, '<td valign="top">Good mix of colors, and well composed. Sharpened a little too much but still a good photo.</td>', 'Good mix of colors, and well composed. Sharpened a little too much but still a good photo.', '2004-11-09 23:20:09.000000', NULL, 1),
(1002189, 116334, 15811, '<td valign="top">What is that?  Looks like partof a tree?  Definately strange-looking, that''s for sure.  Looks like a bunch of moles.  Great subject choice!</td>', 'What is that?  Looks like partof a tree?  Definately strange-looking, that''s for sure.  Looks like a bunch of moles.  Great subject choice!', '2004-11-09 23:20:10.000000', NULL, 1),
