(1009314, 117880, 11738, '<td valign="top">Woohoo!  Finally got that elusive second ribbon!  Thanks to all for the votes and comments.<br/> <br/>This idea came to mind as soon as I saw the challenge title.  I had only seen pictures of the Balancing Rock of Long Island, near Tiverton in local galleries and tourism guides.  So, I jumped in the car at 5 a.m., droved 3.5 hours to the site, hiked in for half and hour and took close to 100 shots.  I wanted to get more shots from different angles, but I was by myself in a very isolated spot... not somewhere to get hurt, so I stayed on the viweing platform.  I plan on returning later to take more pitures.  <br/> <br/>Thanks to my wife Julie for giving me day off to capture this image.  It was an awesome day!<br/><br/><i>Message edited by author 2006-06-20 09:38:47.</i></td>', 'Woohoo!  Finally got that elusive second ribbon!  Thanks to all for the votes and comments. This idea came to mind as soon as I saw the challenge title.  I had only seen pictures of the Balancing Rock of Long Island, near Tiverton in local galleries and tourism guides.  So, I jumped in the car at 5 a.m., droved 3.5 hours to the site, hiked in for half and hour and took close to 100 shots.  I wanted to get more shots from different angles, but I was by myself in a very isolated spot... not somewhere to get hurt, so I stayed on the viweing platform.  I plan on returning later to take more pitures.   Thanks to my wife Julie for giving me day off to capture this image.  It was an awesome day!', '2004-11-13 09:30:20.000000', '2006-06-20 10:38:47.000000', 0),
(1009519, 118069, 19035, '<td valign="top">This deserved much better, great shot.</td>', 'This deserved much better, great shot.', '2004-11-13 12:27:01.000000', NULL, 0),
(1009568, 117159, 22140, '<td valign="top">Yeah - I know the contrast could be better...I was shooting through a wire mesh, hence the ''haze'' some of you mentioned...tried to up contrast/sharpness through that, but enough to compensate for the haze was too much for the rest of the picture...but he manages to look mean anyway. :)</td>', 'Yeah - I know the contrast could be better...I was shooting through a wire mesh, hence the ''haze'' some of you mentioned...tried to up contrast/sharpness through that, but enough to compensate for the haze was too much for the rest of the picture...but he manages to look mean anyway. :)', '2004-11-13 13:27:26.000000', NULL, 0),
(1009763, 116578, 8860, '<td valign="top">Very funny explanation and a striking shot that I remember instantly. Good idea, well executed.</td>', 'Very funny explanation and a striking shot that I remember instantly. Good idea, well executed.', '2004-11-13 19:21:22.000000', NULL, 0),
